// Cloudflare Worker
//
// Routing:
//   - Non-curl UA                  -> 302 redirect to GitHub repo
//   - curl, path "/" or "/install" -> POSIX shell installer (detects arch, re-curls /bin)
//   - curl, path "/bin"            -> serves the right binary based on ?arch= or uname mapping
//   - curl, path "/bin/<arch>"     -> serves a specific arch directly
//
// Payload format per arch: gzip-compressed binary, then base64-encoded.
// Generate all four with generate-payloads.ps1 and paste into PAYLOADS below.

const PAYLOADS = {
  x86_64 : "",
  aarch64: "",
  armv7  : "",
  i386   : "",
};


// Map values of `uname -m` to our arch keys.
const UNAME_MAP = {
  x86_64:  "x86_64",
  amd64:   "x86_64",
  aarch64: "aarch64",
  arm64:   "aarch64",
  armv7l:  "armv7",
  armv7:   "armv7",
  armhf:   "armv7",
  i386:    "i386",
  i486:    "i386",
  i586:    "i386",
  i686:    "i386",
};

const FILE_NAME = "dirtyfrag";
const FILE_MIME = "application/octet-stream";
const REDIRECT_URL = "https://github.com/l5z12/dirtyfrag-worker";

function base64ToBytes(b64) {
  const clean = b64.replace(/\s+/g, "");
  const bin = atob(clean);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function gunzip(bytes) {
  const stream = new Response(bytes).body.pipeThrough(
    new DecompressionStream("gzip")
  );
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

function resolveArch(raw) {
  if (!raw) return null;
  const k = raw.toLowerCase().trim();
  return UNAME_MAP[k] || (PAYLOADS[k] !== undefined ? k : null);
}

async function serveBinary(arch) {
  const b64 = PAYLOADS[arch];
  if (!b64) {
    return new Response(`no payload for arch '${arch}'\n`, { status: 404 });
  }
  const bytes = await gunzip(base64ToBytes(b64));
  return new Response(bytes, {
    status: 200,
    headers: {
      "Content-Type": FILE_MIME,
      "Content-Disposition": `attachment; filename="${FILE_NAME}-${arch}"`,
      "Content-Length": String(bytes.length),
      "Cache-Control": "no-store",
    },
  });
}

function serveInstaller(origin) {
  // POSIX sh installer. Pipes the binary to a temp file, chmods, runs it.
  const sh = `#!/bin/sh
# Verbose installer for dirtyfrag
# Use:  curl -fsSL https://dirtyfrag.l5z12.dev/install | sh
set -eu

ORIGIN="\${ORIGIN:-https://dirtyfrag.l5z12.dev}"

log() { printf '[install] %s\n' "$*" >&2; }
die() { printf '[install] ERROR: %s\n' "$*" >&2; exit 1; }

log "starting installer"
log "origin: $ORIGIN"

# ---- detect arch ----
raw_arch=$(uname -m 2>/dev/null || echo unknown)
log "uname -m: $raw_arch"

case "$raw_arch" in
  x86_64|amd64)              arch=x86_64 ;;
  aarch64|arm64)             arch=aarch64 ;;
  armv7l|armv7|armhf)        arch=armv7 ;;
  i386|i486|i586|i686)       arch=i386 ;;
  *) die "unsupported arch '$raw_arch'" ;;
esac
log "resolved arch: $arch"

# ---- check tools ----
command -v curl  >/dev/null 2>&1 || die "curl not found"
command -v mktemp >/dev/null 2>&1 || die "mktemp not found"
command -v chmod >/dev/null 2>&1 || die "chmod not found"
log "required tools present"

# ---- temp file ----
tmp=$(mktemp 2>/dev/null) || die "mktemp failed"
log "temp file: $tmp"
trap 'log "cleaning up $tmp"; rm -f "$tmp"' EXIT INT TERM

# ---- check /tmp is exec ----
if mount 2>/dev/null | grep -E " on $(dirname "$tmp") " | grep -q noexec; then
  log "WARNING: $(dirname "$tmp") is mounted noexec, trying \$HOME instead"
  rm -f "$tmp"
  tmp="\${HOME:-.}/.dirtyfrag.$$"
  log "new temp file: $tmp"
fi

# ---- download ----
url="\${ORIGIN}/bin?arch=\${arch}"
log "downloading: $url"
if ! curl -fSL --progress-bar "$url" -o "$tmp"; then
  die "download failed"
fi
size=$(wc -c < "$tmp" 2>/dev/null || echo "?")
log "downloaded $size bytes"

# ---- chmod ----
log "chmod +x $tmp"
chmod +x "$tmp" || die "chmod failed"

# ---- run ----
log "executing $tmp $*"
log "(re-attaching stdin to /dev/tty so the binary is interactive)"
log "------------------------------------------------------------"

if [ -e /dev/tty ]; then
  exec "$tmp" "$@" </dev/tty
else
  log "WARNING: no /dev/tty available, running with current stdin"
  exec "$tmp" "$@"
fi
`;
  return new Response(sh, {
    status: 200,
    headers: {
      "Content-Type": "text/x-shellscript; charset=utf-8",
      "Cache-Control": "no-store",
    },
  });
}

export default {
  async fetch(request) {
    const ua = (request.headers.get("user-agent") || "").toLowerCase();
    const isCurl = ua.includes("curl");

    if (!isCurl) {
      return Response.redirect(REDIRECT_URL, 302);
    }

    const url = new URL(request.url);
    const path = url.pathname.replace(/\/+$/, "") || "/";

    // /bin/<arch>
    const m = path.match(/^\/bin\/([A-Za-z0-9_]+)$/);
    if (m) {
      const arch = resolveArch(m[1]);
      if (!arch) return new Response(`unknown arch '${m[1]}'\n`, { status: 400 });
      return serveBinary(arch);
    }

    // /bin?arch=...
    if (path === "/bin") {
      const raw = url.searchParams.get("arch") || "";
      const arch = resolveArch(raw);
      if (!arch) return new Response(`unknown or missing arch '${raw}'\n`, { status: 400 });
      return serveBinary(arch);
    }

    // / or /install -> shell installer
    if (path === "/" || path === "/install") {
      return serveInstaller(url.origin);
    }

    return new Response("not found\n", { status: 404 });
  },
};

